CREATE TABLE IF NOT EXISTS ml_dataset_versions (id INTEGER PRIMARY KEY, dataset_id VARCHAR(160) NOT NULL, version VARCHAR(80) NOT NULL, source TEXT NOT NULL, checksum VARCHAR(64) NOT NULL, record_count INTEGER NOT NULL, class_distribution_json TEXT NOT NULL DEFAULT '{}', quality_json TEXT NOT NULL DEFAULT '{}', preprocessing_version VARCHAR(120) NOT NULL, validation_status VARCHAR(30) NOT NULL DEFAULT 'PENDING', approval_status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_by VARCHAR(512) NOT NULL, created_at TIMESTAMP, UNIQUE(dataset_id, version));
CREATE INDEX IF NOT EXISTS ix_ml_dataset_versions_dataset_id ON ml_dataset_versions(dataset_id);
CREATE TABLE IF NOT EXISTS ml_model_versions (id INTEGER PRIMARY KEY, model_id VARCHAR(160) NOT NULL, version VARCHAR(80) NOT NULL, name VARCHAR(255) NOT NULL, algorithm VARCHAR(120) NOT NULL, dataset_version_id INTEGER, artifact_location TEXT NOT NULL, artifact_checksum VARCHAR(64) NOT NULL, feature_config_json TEXT NOT NULL DEFAULT '{}', hyperparameters_json TEXT NOT NULL DEFAULT '{}', metrics_json TEXT NOT NULL DEFAULT '{}', status VARCHAR(30) NOT NULL DEFAULT 'CANDIDATE', approval_by VARCHAR(512), approved_at TIMESTAMP, created_by VARCHAR(512) NOT NULL, created_at TIMESTAMP, UNIQUE(model_id, version), FOREIGN KEY(dataset_version_id) REFERENCES ml_dataset_versions(id));
CREATE INDEX IF NOT EXISTS ix_ml_model_versions_model_id ON ml_model_versions(model_id);
CREATE TABLE IF NOT EXISTS ml_deployment_history (id INTEGER PRIMARY KEY, model_version_id INTEGER NOT NULL, previous_model_version_id INTEGER, action VARCHAR(30) NOT NULL, actor VARCHAR(512) NOT NULL, artifact_checksum VARCHAR(64) NOT NULL, created_at TIMESTAMP, reason TEXT, FOREIGN KEY(model_version_id) REFERENCES ml_model_versions(id));
CREATE INDEX IF NOT EXISTS ix_ml_deployment_history_model_version_id ON ml_deployment_history(model_version_id);
CREATE TABLE IF NOT EXISTS ml_training_runs (id INTEGER PRIMARY KEY, dataset_version_id INTEGER NOT NULL, model_version_id INTEGER, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', metrics_json TEXT DEFAULT '{}', error TEXT, started_at TIMESTAMP, completed_at TIMESTAMP, created_by VARCHAR(512) NOT NULL, created_at TIMESTAMP, FOREIGN KEY(dataset_version_id) REFERENCES ml_dataset_versions(id), FOREIGN KEY(model_version_id) REFERENCES ml_model_versions(id));
